VALUES('76fdc6fc9e1947fd82189f2eb7a5f31d','单一资产投资限额(穿透后)','LIMIT_TRAN','${DYZCGMCTH}','SUPERVISION','01,02,03','DAYTIME,DAYEND', null , '{"threshold_1":{"op":">=","value":"2700000.0000","unit":"WRMB","is_model":"02"}}' , '{"threshold_1":{"op":">=","value":"3000000.0000","unit":"WRMB","is_model":"02"}}'  , '{"threshold_1":{"op":">=","unit":"WRMB","is_model":"02"}}' , 'N' , null , '01' , null ,'system',null,sysdate,'system',sysdate, '03' , null , null , null  , null , null  , 'Y' , '《关于规范金融机构资产管理业务的指导意见》第15条  金融机构不得违反金融监督管理部门的规定，通过为单一融资项目设立多只资产管理产品的方式，变相突破投资人数限制或者其他监管要求。同一金融机构发行多只资产管理产品投资同一资产的，为防止同一资产发生风险波及多只资产管理产品，多只资产管理产品投资该资产的资金总规模合计不得超过300亿元。如果超出该限额，需经相关金融监督管理部门批准。' , 'SUP065055' );
